RiskCopula$simulate <- function(marginals, n_sims, seed, dims, keys) .Call(wrap__RiskCopula__simulate, self, marginals, n_sims, seed, dims, keys)

#' @export
`$.RiskCopula` <- function (self, name) { func <- RiskCopula[[name]]; environment(func) <- environment(); func }

#' @export
`[[.RiskCopula` <- `$.RiskCopula`
